window.docContents[158].resolve({"/Characters-of-the-cyclotomic-Galois-group/Even-and-odd-characters/#Kummer___s-Criterion-and-Regular-Primes-in-Lean--Characters-of-the-cyclotomic-Galois-group--Even-and-odd-characters":{"contents":"A Dirichlet character  is even if  and odd if\n.\n\nExactly half of the characters modulo  are even and exactly half are odd. The\neven characters are precisely those that factor through the quotient\n, which is the Galois group of the\nmaximal real subfield . This parity distinction is the source\nof the even/odd decomposition in the analytic class number formula.\n\nFinally, because  is prime, every non-trivial Dirichlet character modulo  is\nprimitive. Hence the functional equation for primitive Dirichlet -functions\napplies to every odd character that appears later.\n\n\n","context":"Kummer's Criterion and Regular Primes in Lean\u0009Characters of the cyclotomic Galois group","header":"2.3. Even and odd characters","id":"/Characters-of-the-cyclotomic-Galois-group/Even-and-odd-characters/#Kummer___s-Criterion-and-Regular-Primes-in-Lean--Characters-of-the-cyclotomic-Galois-group--Even-and-odd-characters"}});